# Партнёры OnlyGuests (партнёрство — 10 000 ₸): id заведения → дата начала. Помечаются «Реклама».
PARTNERS = {}

import re
def slug(s):
    tr = dict(zip("абвгдеёжзийклмнопрстуфхцчшщъыьэюяәғқңөұүһі", ["a","b","v","g","d","e","e","zh","z","i","y","k","l","m","n","o","p","r","s","t","u","f","h","ts","ch","sh","sch","","y","","e","yu","ya","a","g","k","n","o","u","u","h","i"]))
    s = "".join(tr.get(c, c) for c in s.lower())
    return re.sub(r"[^a-z0-9]+", "-", s).strip("-")

def photos(i, kitchen):
    out = []
    for k, theme in enumerate(PHOTO_PLAN[kitchen]):
        pool = P[theme]
        pid = pool[(i * 7 + k * 3) % len(pool)]
        j = 0
        while pid in out:
            j += 1; pid = pool[(i * 7 + k * 3 + j) % len(pool)]
        out.append(pid)
    return out

def menu(v):
    scale = (6000 if v["checkApprox"] else v["check"]) / 6000
    scale = max(0.55, min(scale, 2.6)) if v["kitchen"] not in ("canteen", "doner", "store", "konbini") else 1
    def r(x): return int(round(x * scale / 50.0) * 50) if x * scale > 600 else int(round(x * scale / 10.0) * 10)
    base = [(n, r(p)) for n, p in MENU[v["kitchen"]]]
    sig = [(n, p) for n, p in v["sig"]]
    names = {n for n, _ in sig}
    return [{"name": n, "price": p, "signature": True} for n, p in sig] + \
           [{"name": n, "price": p} for n, p in base if n not in names][: max(4, 7 - len(sig))]

import os
_geo_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "geo_cache.json")
GEO = json.load(open(_geo_path, encoding="utf-8")) if os.path.exists(_geo_path) else {}

out = []
seen = set()
for i, v in enumerate(V):
    s = slug(v["name"]) or f"place-{i}"
    while s in seen: s += "-2"
    seen.add(s)
    out.append({
        "id": s, "name": v["name"], "type": v["type"], "cuisine": v["cuisine"], "kitchen": v["kitchen"],
        "rating": v["rating"], "votes": v["votes"], "ratingApprox": v["approx"],
        "address": v["address"], "gis": v["gis"],
        "opened": v["year"], "openedApprox": v["yearApprox"], "openedNote": v["yearNote"],
        "check": v["check"], "checkApprox": v["checkApprox"], "features": v["feat"], "about": v["about"],
        "photos": [U + p + ".jpg" for p in photos(i, v["kitchen"])],
        "menu": menu(v),
    })
    g = GEO.get(s, {})
    if g.get("lat"):
        out[-1].update(lat=g["lat"], lon=g["lon"])
    if g.get("district"):
        out[-1]["district"] = g["district"]
    if HOURS.get(v["name"]) or g.get("hours"):
        out[-1]["hours"] = HOURS.get(v["name"]) or g["hours"]
    if s in PARTNERS:
        out[-1]["partner"] = True

js = "// OnlyGuests — данные о %d заведениях Алматы.\n" % len(out) + \
     "// Рейтинги и число оценок — по карточкам 2ГИС на октябрь 2026 г. (могут меняться).\n" \
     "// opened — год открытия, если его удалось подтвердить источником; openedNote — пояснение.\n" \
     "// menu — популярные позиции с ориентировочными ценами (₸); фото — иллюстративные (Unsplash).\n" \
     "window.CAFES = " + json.dumps(out, ensure_ascii=False, indent=1) + ";\n"
open(sys.argv[1], "w").write(js)
print(len(out), "places;", sum(1 for o in out if o["opened"]), "with year")
